#include <iostream>
#include <string>
int main() {
    int age;
    std::string name;
    std::cin >> age;
    std::cin.ignore(); // Xóa dấu '\n' còn sót
    std::getline(std::cin, name);
    std::cout << name << " - " << age << '\n';
}

